313:    public void ShiftLocalFrame(float deltaXCm, float deltaYCm)
314:    {
315:        if (deltaXCm == 0f && deltaYCm == 0f)
316:        {
317:            return;
318:        }
319:
320:        int scalarCount = UnitCount * 2;
321:        for (int offset = 0; offset < scalarCount; offset += 2)
322:        {
323:            _positionsCm[offset] -= deltaXCm;
324:            _positionsCm[offset + 1] -= deltaYCm;
325:            _readPositionsCm[offset] -= deltaXCm;
326:            _readPositionsCm[offset + 1] -= deltaYCm;
327:            _unitProgressAnchorCm[offset] -= deltaXCm;
