333:                _unitTargetsCm[offset] -= deltaXCm;
334:                _unitTargetsCm[offset + 1] -= deltaYCm;
335:            }
336:        }
337:
338:        for (int teamIndex = 0; teamIndex < _teamStates.Count; teamIndex++)
339:        {
340:            TeamRuntimeState team = _teamStates[teamIndex];
341:            team.TargetX -= deltaXCm;
