479:    public bool SetUnitRuntimeProfile(
480:        int index,
481:        int teamId,
482:        float navMass,
483:        float visualScale,
484:        float bodyRadiusCm,
485:        float speedCmPerSecond,
486:        MassNavigationAgentLayer layer)
487:    {
488:        if ((uint)index >= (uint)UnitCount)
489:        {
490:            throw new InvalidOperationException(
491:                $"MassNavigationFlow runtime profile agent index {index} exceeds current unit count {UnitCount}.");
492:        }
493:
494:        ValidateRuntimeProfile(index, navMass, visualScale, bodyRadiusCm, speedCmPerSecond);
495:        uint categoryMask = layer.CategoryMask;
496:        uint interactionMask = layer.InteractionMask;
497:        bool changed =
498:            _teams[index] != teamId ||
499:            MathF.Abs(_navMasses[index] - navMass) > float.Epsilon ||
500:            MathF.Abs(_visualScales[index] - visualScale) > float.Epsilon ||
501:            MathF.Abs(_bodyRadiiCm[index] - bodyRadiusCm) > float.Epsilon ||
502:            MathF.Abs(_speedsCmPerSecond[index] - speedCmPerSecond) > float.Epsilon ||
503:            _layerCategoryMasks[index] != categoryMask ||
504:            _layerInteractionMasks[index] != interactionMask;
505:        if (!changed)
506:        {
507:            return false;
508:        }
509:
510:        float previousBodyRadiusCm = _bodyRadiiCm[index];
511:        bool teamOrLayerChanged =
512:            _teams[index] != teamId ||
513:            _layerCategoryMasks[index] != categoryMask ||
514:            _layerInteractionMasks[index] != interactionMask;
515:        _teams[index] = teamId;
516:        if (_teamStateIndexById.TryGetValue(teamId, out int teamStateIndex))
517:        {
518:            _teamRuntimeIndices[index] = teamStateIndex;
519:        }
520:
521:        _navMasses[index] = navMass;
522:        _visualScales[index] = visualScale;
523:        _bodyRadiiCm[index] = bodyRadiusCm;
524:        _speedsCmPerSecond[index] = speedCmPerSecond;
525:        if (bodyRadiusCm >= _maxBodyRadiusCm)
