529:        else if (MathF.Abs(previousBodyRadiusCm - _maxBodyRadiusCm) <= float.Epsilon)
530:        {
531:            RecomputeMaxBodyRadiusCm();
532:        }
533:
534:        _layerCategoryMasks[index] = categoryMask;
535:        _layerInteractionMasks[index] = interactionMask;
536:        _maxInteractingBodyRadiiDirty = true;
537:        if ((uint)_teamRuntimeIndices[index] < (uint)_teamStates.Count)
538:        {
