932:    internal void Step(
933:        float dt,
934:        World world,
935:        MassNavigationGroupRuntime navGroupRuntime,
936:        bool runHardResolve,
937:        int hardResolveCandidateThresholdAgents,
938:        Action<double>? observeStepPrep = null,
939:        Action<double>? observeLocalSteering = null,
940:        Action<double>? observeHardResolve = null)
941:    {
942:        if (UnitCount <= 0)
943:        {
944:            return;
945:        }
946:
947:        long prepStart = System.Diagnostics.Stopwatch.GetTimestamp();
948:        RefreshTeamRelationshipMatrixIfStale();
949:
950:        float clampedDt = Math.Clamp(dt, 0f, Semantics.Solver.MaxStepDtSeconds);
951:        _frameCount++;
952:        int scalarCount = UnitCount * 2;
953:        Array.Copy(_positionsCm, _readPositionsCm, scalarCount);
954:        Array.Copy(_velocitiesCm, _readVelocitiesCm, scalarCount);
955:        _useCandidateGating = UnitCount >= Math.Max(1, hardResolveCandidateThresholdAgents);
956:        if (_useCandidateGating)
957:        {
958:            Array.Clear(_hardResolveCandidates, 0, UnitCount);
959:            for (int displacedIndex = 0; displacedIndex < _displacedAgentCount; displacedIndex++)
960:            {
961:                _hardResolveCandidates[_displacedAgents[displacedIndex]] = 1;
962:            }
963:        }
964:
965:        float sepRadiusCm = Semantics.Steering.SeparationRadiusCm;
966:        float sepRadiusSq = sepRadiusCm * sepRadiusCm;
967:        float arrivalRadiusCm = Semantics.Steering.GoalArrivalRadiusCm;
968:        float arrivalRadiusSq = arrivalRadiusCm * arrivalRadiusCm;
969:        float unitTargetStopThresholdCm = Semantics.Group.UnitTargetStopThresholdCm;
970:        float unitTargetStopThresholdSq = unitTargetStopThresholdCm * unitTargetStopThresholdCm;
971:
972:        RecomputeMaxInteractingBodyRadiiCmIfDirty();
973:        BuildSeparationHash(_readPositionsCm);
974:        observeStepPrep?.Invoke((System.Diagnostics.Stopwatch.GetTimestamp() - prepStart) * 1000.0 / System.Diagnostics.Stopwatch.Frequency);
975:
976:        int hwm1 = _separationHashWidth - 1;
977:        int hhm1 = _separationHashHeight - 1;
978:        float invHashCell = 1f / _separationHashCellSizeCm;
979:        int flowObstacleNeighborRadiusCells = Semantics.Solver.FlowObstacleNeighborRadiusCells;
980:
981:        int workerCount = Math.Min(_parallelWorkerCount, UnitCount);
982:        if (workerCount <= 1 || UnitCount < Semantics.Solver.ParallelStepMinAgents)
983:        {
984:            long steeringStart = System.Diagnostics.Stopwatch.GetTimestamp();
985:            StepRange(0, UnitCount, scratchWorkerIndex: 0, clampedDt, navGroupRuntime, sepRadiusSq, sepRadiusCm, arrivalRadiusCm, arrivalRadiusSq, unitTargetStopThresholdSq, hwm1, hhm1, invHashCell, flowObstacleNeighborRadiusCells, _useCandidateGating);
986:            observeLocalSteering?.Invoke((System.Diagnostics.Stopwatch.GetTimestamp() - steeringStart) * 1000.0 / System.Diagnostics.Stopwatch.Frequency);
987:            ClampAllPositionsToWorldBounds();
988:            long resolveStart = System.Diagnostics.Stopwatch.GetTimestamp();
989:            if (runHardResolve)
990:            {
991:                ResolveHardPenetration();
992:                ClampAllPositionsToWorldBounds();
993:            }
994:            observeHardResolve?.Invoke((System.Diagnostics.Stopwatch.GetTimestamp() - resolveStart) * 1000.0 / System.Diagnostics.Stopwatch.Frequency);
995:            UpdateSettledUnitCount();
996:            MarkMovedEntitiesDirty();
997:            return;
998:        }
999:
1000:        var scheduler = World.SharedJobScheduler ?? throw new InvalidOperationException(
1001:            "MassNavigationFlowSolverState requires World.SharedJobScheduler when solver.parallelWorkerCount requests parallel stepping.");
1002:        int baseCount = UnitCount / workerCount;
1003:        int remainder = UnitCount % workerCount;
1004:        int startIndex = 0;
1005:        long threadedSteeringStart = System.Diagnostics.Stopwatch.GetTimestamp();
1006:        for (int workerIndex = 0; workerIndex < workerCount; workerIndex++)
1007:        {
1008:            int length = baseCount + (workerIndex < remainder ? 1 : 0);
1009:            var job = _stepJobs[workerIndex];
1010:            job.Owner = this;
1011:            job.StartIndex = startIndex;
1012:            job.EndIndex = startIndex + length;
1013:            job.ScratchWorkerIndex = workerIndex;
1014:            job.Dt = clampedDt;
1015:            job.NavGroupRuntime = navGroupRuntime;
1016:            job.SepRadiusSq = sepRadiusSq;
1017:            job.SepRadiusCm = sepRadiusCm;
1018:            job.ArrivalRadiusCm = arrivalRadiusCm;
1019:            job.ArrivalRadiusSq = arrivalRadiusSq;
1020:            job.UnitTargetStopThresholdSq = unitTargetStopThresholdSq;
1021:            job.HashWidthMinusOne = hwm1;
1022:            job.HashHeightMinusOne = hhm1;
1023:            job.InvHashCell = invHashCell;
1024:            job.FlowObstacleNeighborRadiusCells = flowObstacleNeighborRadiusCells;
1025:            job.UseCandidateGating = _useCandidateGating;
1026:            _stepHandles[workerIndex] = scheduler.Schedule(job);
1027:            startIndex += length;
1028:        }
1029:
1030:        scheduler.Flush();
1031:        for (int workerIndex = 0; workerIndex < workerCount; workerIndex++)
1032:        {
1033:            _stepHandles[workerIndex].Complete();
1034:        }
1035:        observeLocalSteering?.Invoke((System.Diagnostics.Stopwatch.GetTimestamp() - threadedSteeringStart) * 1000.0 / System.Diagnostics.Stopwatch.Frequency);
1036:
1037:        ClampAllPositionsToWorldBounds();
1038:        long hardResolveStart = System.Diagnostics.Stopwatch.GetTimestamp();
1039:        if (runHardResolve)
