49:            if (TryGetHashCell(positionsCm, i, invHashCell, hashWidthMinusOne, hashHeightMinusOne, hashWidth, out int cell))
50:            {
51:                cellCounts[cell]++;
52:            }
53:        }
54:
55:        int offset = 0;
56:        for (int cell = 0; cell < cellCounts.Length; cell++)
57:        {
58:            cellOffsets[cell] = offset;
59:            cellCursor[cell] = offset;
60:            offset += cellCounts[cell];
61:        }
62:
63:        for (int i = 0; i < UnitCount; i++)
64:        {
65:            if (TryGetHashCell(positionsCm, i, invHashCell, hashWidthMinusOne, hashHeightMinusOne, hashWidth, out int cell))
66:            {
67:                cellAgents[cellCursor[cell]++] = i;
68:            }
69:        }
70:    }
