72:    private static bool TryGetHashCell(
73:        float[] positionsCm,
74:        int index,
75:        float invHashCell,
76:        int hashWidthMinusOne,
77:        int hashHeightMinusOne,
78:        int hashWidth,
79:        out int cell)
80:    {
81:        int i2 = index << 1;
82:        int cellX = (int)(positionsCm[i2] * invHashCell);
83:        int cellY = (int)(positionsCm[i2 + 1] * invHashCell);
84:        if ((uint)cellX > (uint)hashWidthMinusOne || (uint)cellY > (uint)hashHeightMinusOne)
85:        {
86:            cell = -1;
87:            return false;
88:        }
89:
90:        cell = (cellY * hashWidth) + cellX;
91:        return true;

