36:        public void Reset(int fixedHz, int targetHz, int maxStepsPerFixedTick)
37:        {
38:            if (fixedHz < 1) throw new ArgumentOutOfRangeException(nameof(fixedHz));
39:            if (targetHz < 0) throw new ArgumentOutOfRangeException(nameof(targetHz));
40:            if (maxStepsPerFixedTick < 1) throw new ArgumentOutOfRangeException(nameof(maxStepsPerFixedTick));
41:
42:            _fixedHz = fixedHz;
43:            _targetHz = targetHz;
44:            _maxStepsPerFixedTick = maxStepsPerFixedTick;
45:
46:            if (targetHz == 0)
47:            {
48:                _numerator = 0;
49:                _denominator = 1;
50:                _remainder = 0;
51:                return;
52:            }
53:
54:            int maxStepsNeeded = (targetHz + fixedHz - 1) / fixedHz;
55:            if (maxStepsNeeded > maxStepsPerFixedTick)
56:            {
57:                throw new InvalidOperationException($"Tick rate requires up to {maxStepsNeeded} steps per fixed tick, exceeding MaxStepsPerFixedTick={maxStepsPerFixedTick}.");
58:            }
59:
60:            _numerator = targetHz;
61:            _denominator = fixedHz;
62:            _remainder = 0;
63:        }
